// normalizeState returns the context to persist: nil and empty slices
// are the same empty context. It never aliases the caller's backing
// array, so later mutation of the argument cannot change saved state.
func normalizeState(state []byte) []byte {
	if len(state) == 0 {
		return nil
	}
	out := make([]byte, len(state))
	copy(out, state)
	return out
}

// cloneState returns a fresh copy of a stored context (nil when empty),
// so mutating the value handed back to a caller can never change the
// checkpoint.
func cloneState(state []byte) []byte {
	if len(state) == 0 {
		return nil
	}
	out := make([]byte, len(state))
	copy(out, state)
	return out
}

// validConsumerName reports whether name is an acceptable consumer
// name. The rule is the idempotency-key rule — non-empty, valid UTF-8,
// NUL-free, at most 256 bytes — but the two namespaces are independent:
// a consumer may share a name with an idempotency key.
func validConsumerName(name string) bool {
	if name == "" || len(name) > maxBatchIDLen {
		return false
	}
	if strings.IndexByte(name, 0) >= 0 {
		return false
	}
	return utf8.ValidString(name)
}

// ackValidate runs the pre-I/O checks shared by both ack entry points
// and returns the registered consumer's current record and whether the
// requested seq advances past it. The check order is fixed by contract:
// name first, then state size, then registration and progress.
//
// A syntactically invalid name returns ErrInvalidConsumer.
func (l *Log) ackValidate(name string, seq uint64, state []byte) (cur consumerStateRec, advance bool, err error) {
	if !validConsumerName(name) {
		return consumerStateRec{}, false, ErrInvalidConsumer
	}
	if len(state) > MaxCheckpointState {
		return consumerStateRec{}, false, ErrInvalidCheckpointState
	}
	cur, registered := l.consumers[name]
	if !registered {
		if seq != 0 {
			return consumerStateRec{}, false, ErrUnknownConsumer
		}
		return cur, false, nil
	}
	switch {
	case seq == cur.seq:
		// Confirming the already-confirmed prefix is idempotent. Whether
		// it is a silent no-op or a conflict depends on the context,
		// checked by the caller.
		return cur, false, nil
	case seq < cur.seq:
		// Checkpoints only move forward.
		return cur, true, ErrInvalidAck
	}
	return cur, true, nil
